create extension if not exists pgtap with schema extensions;
create extension if not exists dblink with schema extensions;
begin;
insert into public.organizations(id,name,slug) values('be500000-0000-4000-8000-000000000010','Concurrent inventory','w5d-concurrent');
insert into public.products(id,org_id,name,type,is_stockable) values('be500000-0000-4000-8000-000000000030','be500000-0000-4000-8000-000000000010','Concurrent goods','goods',true);
insert into public.warehouses(id,org_id,code,name) values('be500000-0000-4000-8000-000000000040','be500000-0000-4000-8000-000000000010','CON-A','Concurrent A'),('be500000-0000-4000-8000-000000000041','be500000-0000-4000-8000-000000000010','CON-B','Concurrent B');
commit;
select no_plan();
select dblink_connect('stock_a','host=host.docker.internal port='||coalesce(nullif(current_setting('test.inventory_dblink_port',true),''),'56102')||' dbname=postgres user=postgres password=postgres');
select dblink_connect('stock_b','host=host.docker.internal port='||coalesce(nullif(current_setting('test.inventory_dblink_port',true),''),'56102')||' dbname=postgres user=postgres password=postgres');
select dblink_exec('stock_a','begin');
select dblink_exec('stock_b','begin');
select dblink_exec('stock_a',$$insert into public.stock_moves(org_id,product_id,warehouse_id,kind,quantity,unit_cost_satang,source_type,source_id,balance_after,average_cost_after) values('be500000-0000-4000-8000-000000000010','be500000-0000-4000-8000-000000000030','be500000-0000-4000-8000-000000000040','receipt',1,100,'adjustment',gen_random_uuid(),0,0)$$);
select dblink_exec('stock_b','set local lock_timeout = ''500ms''');
select lives_ok($$select dblink_exec('stock_b',$q$do $b$ begin perform id from public.products where id='be500000-0000-4000-8000-000000000030' for share; end $b$ $q$)$$,'posting does not block line unit validation');
select lives_ok($$select dblink_exec('stock_b',$q$insert into public.stock_moves(org_id,product_id,warehouse_id,kind,quantity,unit_cost_satang,source_type,source_id,balance_after,average_cost_after) values('be500000-0000-4000-8000-000000000010','be500000-0000-4000-8000-000000000030','be500000-0000-4000-8000-000000000041','receipt',1,100,'adjustment',gen_random_uuid(),0,0)$q$)$$,'different warehouse posts independently');
select dblink_exec('stock_b','set local lock_timeout = ''5s''');
select dblink_send_query('stock_b',$$insert into public.stock_moves(org_id,product_id,warehouse_id,kind,quantity,unit_cost_satang,source_type,source_id,balance_after,average_cost_after) values('be500000-0000-4000-8000-000000000010','be500000-0000-4000-8000-000000000030','be500000-0000-4000-8000-000000000040','receipt',1,200,'adjustment',gen_random_uuid(),0,0)$$);
select pg_sleep(0.05);
select is(dblink_is_busy('stock_b'),1,'same balance posting waits');
select dblink_exec('stock_a','commit');
select * from dblink_get_result('stock_b') as t(status text);
select * from dblink_get_result('stock_b') as t(status text);
select dblink_exec('stock_b','commit');
select is((select quantity from public.stock_balances where warehouse_id='be500000-0000-4000-8000-000000000040'),2::numeric,'concurrent receipts retain both quantities');
select is((select average_cost from public.stock_balances where warehouse_id='be500000-0000-4000-8000-000000000040'),150::numeric,'concurrent receipts retain weighted average');
select dblink_exec('stock_a','begin');
select dblink_exec('stock_b','begin');
select dblink_exec('stock_a',$$insert into public.stock_moves(org_id,product_id,warehouse_id,kind,quantity,unit_cost_satang,source_type,source_id,balance_after,average_cost_after) values('be500000-0000-4000-8000-000000000010','be500000-0000-4000-8000-000000000030','be500000-0000-4000-8000-000000000040','delivery',2,0,'adjustment',gen_random_uuid(),0,0)$$);
select dblink_send_query('stock_b',$$insert into public.stock_moves(org_id,product_id,warehouse_id,kind,quantity,unit_cost_satang,source_type,source_id,balance_after,average_cost_after) values('be500000-0000-4000-8000-000000000010','be500000-0000-4000-8000-000000000030','be500000-0000-4000-8000-000000000040','delivery',2,0,'adjustment',gen_random_uuid(),0,0)$$);
select pg_sleep(0.05);
select is(dblink_is_busy('stock_b'),1,'competing outgoing posting waits');
select dblink_exec('stock_a','commit');
select * from dblink_get_result('stock_b',false) as t(status text);
select matches(dblink_error_message('stock_b'),'Insufficient stock','losing posting refuses negative stock');
select * from dblink_get_result('stock_b',false) as t(status text);
select dblink_exec('stock_b','rollback');
select is((select quantity from public.stock_balances where warehouse_id='be500000-0000-4000-8000-000000000040'),0::numeric,'concurrent outgoing stock cannot oversell');
select dblink_disconnect('stock_a');
select dblink_disconnect('stock_b');
select * from finish();
begin;
alter table public.stock_moves disable trigger retain_stock_move;
delete from public.stock_moves where org_id='be500000-0000-4000-8000-000000000010';
alter table public.stock_moves enable trigger retain_stock_move;
delete from public.stock_balances where org_id='be500000-0000-4000-8000-000000000010';
delete from public.products where org_id='be500000-0000-4000-8000-000000000010';
delete from public.organizations where id='be500000-0000-4000-8000-000000000010';
commit;
